import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Archive, Bell, CalendarDays, CheckSquare, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, FileDown, Filter, Grid2X2, Inbox, LayoutDashboard, LayoutGrid, List, LogOut, Maximize2, Menu, Minimize2, Monitor, Moon, MoreHorizontal, Plus, Search, Settings2, Star, Sun, Table2, Users, WandSparkles, X, Zap } from 'lucide-react';
import { get, post, patch, saveJson } from './api';
import type { Board, BoardDetail, Bootstrap, Card, CardDetail, User, Workspace } from './types';
import { BoardCanvas } from './BoardCanvas';
import { BoardFilterPanel } from './BoardFilterPanel';
import { CardDialog } from './CardDialog';
import { AlternateView } from './Views';
import { BoardAdminPanels } from './BoardAdminPanels';
import { useAppearance, type Appearance } from './appearance';
import { InstallHelp, usePwaInstall } from './pwa';

type Page = 'home' | 'board' | 'inbox' | 'planner' | 'search' | 'settings';
type View = 'board' | 'calendar' | 'table' | 'timeline' | 'dashboard' | 'map';
type Modal = 'workspace' | 'board' | 'invite' | 'automation' | 'board-settings' | null;
const views: { id: View; label: string; icon: typeof LayoutGrid }[] = [
  { id: 'board', label: 'Quadro', icon: LayoutGrid }, { id: 'calendar', label: 'Calendário', icon: CalendarDays },
  { id: 'table', label: 'Tabela', icon: Table2 }, { id: 'timeline', label: 'Linha do tempo', icon: List },
  { id: 'dashboard', label: 'Painel', icon: LayoutDashboard }, { id: 'map', label: 'Mapa', icon: Grid2X2 }
];

function initials(name: string) { return name.trim().split(/\s+/).slice(0, 2).map(s => s[0]?.toUpperCase()).join('') || '?'; }
function notificationText(type: string) { return ({ invite: 'Convite para área de trabalho', board_invite: 'Convite para quadro', assigned: 'Você foi adicionado a um cartão', comment: 'Novo comentário', due: 'Prazo de cartão', mention: 'Você foi mencionado' } as Record<string,string>)[type] || type.replaceAll('_', ' '); }
function Avatar({ person, size = 'normal', title }: { person: Pick<User, 'name'> & { avatarColor?: string }; size?: 'normal' | 'small'; title?: string }) {
  return <span className={`avatar ${size === 'small' ? 'avatar-small' : ''}`} style={{ background: person.avatarColor || '#8060b3' }} title={title || person.name}>{initials(person.name)}</span>;
}
function Dialog({ title, children, onClose, wide = false }: { title: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => { const fn = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn); }, [onClose]);
  return <div className="dialog-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section className={`dialog ${wide ? 'dialog-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><header className="dialog-head"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Fechar"><X size={18} /></button></header>{children}</section></div>;
}
function AuthScreen({ onAuth, onInstall, installed }: { onAuth: (value: User) => void; onInstall: () => void; installed: boolean }) {
  const [mode, setMode] = useState<'login' | 'register'>('register');
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(e: React.FormEvent) {
    e.preventDefault(); setBusy(true); setError('');
    try { const result = await post<{ user: User }>(`/auth/${mode}`, { name, email, password }); onAuth(result.user); }
    catch (err) { setError((err as Error).message); } finally { setBusy(false); }
  }
  return <div className="auth-page"><div className="auth-art"><div className="auth-brand"><span className="brand-mark"><i /><i /><i /></span>Organize</div><h1>O trabalho ganha forma quando a equipe se encontra.</h1><p>Transforme ideias em tarefas claras, acompanhe cada etapa e celebre o que foi feito.</p><div className="auth-demo-board"><div><span>Planejar</span><b>Ideias para a semana</b><b>Definir prioridades</b></div><div><span>Em andamento</span><b>Preparar lançamento</b><b>Revisar apresentação</b></div><div><span>Concluído</span><b>Primeira reunião <em>✓</em></b></div></div></div><div className="auth-side"><form className="auth-card" onSubmit={submit}><div className="brand auth-mobile-brand"><span className="brand-mark"><i /><i /><i /></span><strong>Organize</strong></div><h2>{mode === 'register' ? 'Comece a organizar' : 'Boas-vindas de volta'}</h2><p>{mode === 'register' ? 'Crie sua conta gratuita para começar.' : 'Entre para continuar de onde parou.'}</p>{mode === 'register' && <label>Nome completo<input autoComplete="name" required value={name} onChange={e => setName(e.target.value)} placeholder="Seu nome" /></label>}<label>Email<input type="email" autoComplete="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="voce@exemplo.com" /></label><label>Senha<input type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} minLength={8} required value={password} onChange={e => setPassword(e.target.value)} placeholder="Pelo menos 8 caracteres" /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-button auth-submit" disabled={busy}>{busy ? 'Aguarde…' : mode === 'register' ? 'Criar conta' : 'Entrar'}</button><button type="button" className="secondary-button auth-install" onClick={onInstall} disabled={installed}>{installed ? 'Organize instalado' : 'Instalar Organize no celular'}</button><div className="auth-switch">{mode === 'register' ? 'Já tem uma conta?' : 'Ainda não tem uma conta?'} <button type="button" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }}>{mode === 'register' ? 'Entrar' : 'Criar conta'}</button></div></form></div></div>;
}

export default function App() {
  const [boot, setBoot] = useState<Bootstrap | null>(null); const [loading, setLoading] = useState(true);
  const [page, setPage] = useState<Page>('home'); const [boardId, setBoardId] = useState<string | null>(null);
  const [detail, setDetail] = useState<BoardDetail | null>(null); const [view, setView] = useState<View>('board');
  const [cardId, setCardId] = useState<string | null>(null); const [cardDetail, setCardDetail] = useState<CardDetail | null>(null);
  const [modal, setModal] = useState<Modal>(null); const [sidebarOpen, setSidebarOpen] = useState(false); const [topMenu, setTopMenu] = useState<'create'|'boards'|'recent'|'favorites'|'templates'|'notifications'|'profile'|null>(null);
  const [boardFocus, setBoardFocus] = useState(() => localStorage.getItem('organize-board-focus') === 'true');
  useEffect(() => { localStorage.setItem('organize-board-focus', String(boardFocus)); }, [boardFocus]);
  const [recentIds, setRecentIds] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem('organize-recent-boards') || '[]'); } catch { return []; } });
  const [templateCards, setTemplateCards] = useState<Array<Card & { boardTitle: string }>>([]);
  const [query, setQuery] = useState(''); const [searchResults, setSearchResults] = useState<{ boards?: Board[]; cards?: Card[] }>({});
  const [filterOpen, setFilterOpen] = useState(false); const [filterText, setFilterText] = useState(''); const [filterLabel, setFilterLabel] = useState(''); const [filterMember, setFilterMember] = useState(''); const [filterDue, setFilterDue] = useState('');
  const [toast, setToast] = useState(''); const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const processedInvite = useRef<string | null>(null);
  const [workspaceName, setWorkspaceName] = useState(''); const [newBoardTitle, setNewBoardTitle] = useState(''); const [newBoardWorkspace, setNewBoardWorkspace] = useState(''); const [newBoardVisibility, setNewBoardVisibility] = useState<Board['visibility']>('workspace');
  const [inviteEmail, setInviteEmail] = useState(''); const [inviteRole, setInviteRole] = useState('member'); const [inviteLink, setInviteLink] = useState('');
  const [automationName, setAutomationName] = useState(''); const [automationTrigger, setAutomationTrigger] = useState('card_moved'); const [automationAction, setAutomationAction] = useState('mark_complete'); const [automationValue, setAutomationValue] = useState('');

  const flash = useCallback((message: string) => { setToast(message); if (toastTimer.current) clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 4500); }, []);
  const theme = useAppearance(boot?.user?.id, flash);
  const pwa = usePwaInstall();
  const loadBootstrap = useCallback(async () => { try { const data = await get<Bootstrap>('/bootstrap'); setBoot(data); return data; } catch (err) { if ((err as { status?: number }).status === 401) { setBoot(null); return null; } flash((err as Error).message); return null; } finally { setLoading(false); } }, [flash]);
  const loadBoard = useCallback(async (id: string) => { try { const data = await get<BoardDetail>(`/boards/${id}`); setDetail(data); return data; } catch (err) { flash((err as Error).message); return null; } }, [flash]);
  const loadCard = useCallback(async (id: string) => { try { const data = await get<CardDetail>(`/cards/${id}`); setCardDetail(data); return data; } catch (err) { flash((err as Error).message); return null; } }, [flash]);
  useEffect(() => { loadBootstrap().then(data => { const match = window.location.pathname.match(/^\/b\/([^/]+)/); if (data && match) { setBoardId(match[1]); setPage('board'); } }); }, [loadBootstrap]);
  useEffect(() => { const token = window.location.pathname.match(/^\/invite\/([^/]+)/)?.[1]; if (!boot?.user || !token) return; const attempt = `${boot.user.id}:${token}`; if (processedInvite.current === attempt) return; processedInvite.current = attempt; post(`/invites/${token}/accept`).then(() => { window.history.replaceState({}, '', '/'); setPage('home'); loadBootstrap(); flash('Convite aceito. A área de trabalho já está disponível.'); }).catch(err => { if (processedInvite.current === attempt) processedInvite.current = null; flash((err as Error).message); }); }, [boot?.user?.id, loadBootstrap, flash]);
  useEffect(() => { if (boardId && page === 'board') loadBoard(boardId); }, [boardId, page, loadBoard]);
  useEffect(() => { if (cardId) loadCard(cardId); else setCardDetail(null); }, [cardId, loadCard]);
  useEffect(() => { if (!boot?.user) return; const events = new EventSource('/api/events'); const refresh = () => { loadBootstrap(); if (boardId) loadBoard(boardId); if (cardId) loadCard(cardId); }; events.addEventListener('change', refresh); events.onmessage = refresh; return () => events.close(); }, [boot?.user?.id, boardId, cardId, loadBootstrap, loadBoard, loadCard]);
  useEffect(() => { if (page !== 'search' || !query.trim()) { setSearchResults({}); return; } const t = setTimeout(() => { get<{ boards?: Board[]; cards?: Card[] }>(`/search?q=${encodeURIComponent(query)}`).then(setSearchResults).catch(err => flash((err as Error).message)); }, 250); return () => clearTimeout(t); }, [query, page, flash]);
  useEffect(() => { if (topMenu !== 'templates' || !boot) return; let cancelled = false; Promise.all(boot.boards.map(async board => { try { const result = await get<{ cards: Card[] }>(`/boards/${board.id}/templates`); return (result.cards || []).map(card => ({ ...card, boardTitle: board.title })); } catch { return []; } })).then(groups => { if (!cancelled) setTemplateCards(groups.flat()); }); return () => { cancelled = true; }; }, [topMenu, boot?.boards]);
  const openBoard = useCallback((id: string) => { setBoardId(id); setView('board'); setPage('board'); setSidebarOpen(false); setTopMenu(null); setRecentIds(previous => { const next = [id, ...previous.filter(value => value !== id)].slice(0, 8); localStorage.setItem('organize-recent-boards', JSON.stringify(next)); return next; }); window.history.pushState({}, '', `/b/${id}`); }, []);
  const navigate = useCallback((next: Page) => { setPage(next); setSidebarOpen(false); setTopMenu(null); if (next !== 'board') { setBoardId(null); setDetail(null); window.history.pushState({}, '', next === 'home' ? '/' : `/${next}`); } }, []);
  useEffect(() => { const fn = (event: PopStateEvent) => { void event; const match = window.location.pathname.match(/^\/b\/([^/]+)/); if (match) { setBoardId(match[1]); setPage('board'); } else { setBoardId(null); setPage((window.location.pathname.slice(1) as Page) || 'home'); } }; window.addEventListener('popstate', fn); return () => window.removeEventListener('popstate', fn); }, []);
  const mutate = useCallback(async <T,>(request: () => Promise<T>, message?: string, refreshCard = false) => { try { const value = await request(); if (message) flash(message); await Promise.all([loadBootstrap(), boardId ? loadBoard(boardId) : Promise.resolve(), refreshCard && cardId ? loadCard(cardId) : Promise.resolve()]); return value; } catch (err) { flash((err as Error).message); return null; } }, [boardId, cardId, flash, loadBootstrap, loadBoard, loadCard]);
  useEffect(() => { const fn = (e: KeyboardEvent) => { const target = e.target as HTMLElement; if (e.key === 'Escape' && document.querySelector('.card-dialog')) return; if (target.closest('input, textarea, [contenteditable="true"]') || e.ctrlKey || e.metaKey || e.altKey || (document.querySelector('[role="dialog"]') && e.key !== 'Escape')) return; if (e.key === '/') { e.preventDefault(); navigate('search'); setTimeout(() => document.querySelector<HTMLInputElement>('.search-page-input')?.focus(), 0); } if (e.key.toLowerCase() === 'b') { e.preventDefault(); setTopMenu(v => v === 'boards' ? null : 'boards'); } if (e.key.toLowerCase() === 'f' && page === 'board') { e.preventDefault(); setFilterOpen(v => !v); } if (e.key.toLowerCase() === 'n' && page === 'board') { e.preventDefault(); document.querySelector<HTMLButtonElement>('.add-card-trigger')?.click(); } if (e.key === 'Escape') { setTopMenu(null); setFilterOpen(false); setCardId(null); setModal(null); } }; document.addEventListener('keydown', fn); return () => document.removeEventListener('keydown', fn); }, [navigate, page]);

  const currentBoard = detail?.board || boot?.boards.find(b => b.id === boardId);
  const filteredCards = useMemo(() => detail?.cards.filter(card => { if (card.archived) return false; if (filterText && !`${card.title} ${card.description || ''}`.toLowerCase().includes(filterText.toLowerCase())) return false; if (filterLabel && !card.labelIds?.includes(filterLabel)) return false; if (filterMember && !card.memberIds?.includes(filterMember)) return false; if (filterDue === 'overdue' && (!card.dueAt || new Date(card.dueAt) >= new Date() || card.completed)) return false; if (filterDue === 'today' && (!card.dueAt || new Date(card.dueAt).toDateString() !== new Date().toDateString())) return false; return true; }) || [], [detail?.cards, filterText, filterLabel, filterMember, filterDue]);
  if (loading) return <div className="loading-screen"><span className="brand-mark"><i /><i /><i /></span><strong>Organize</strong></div>;
  if (!boot) return <><AuthScreen onAuth={user => { setBoot({ user, workspaces: [], boards: [], notifications: [] }); loadBootstrap(); }} onInstall={() => void pwa.install()} installed={pwa.installed} />{pwa.helpOpen && <InstallHelp onClose={pwa.closeHelp} />}</>;
  const ownerWorkspace = currentBoard?.workspaceId || boot.workspaces[0]?.id;
  const createWorkspace = async (e: React.FormEvent) => { e.preventDefault(); const result = await mutate(() => post<{ workspace: Workspace }>('/workspaces', { name: workspaceName }), 'Área de trabalho criada'); if (result?.workspace) { setModal(null); setWorkspaceName(''); } };
  const createBoard = async (e: React.FormEvent) => { e.preventDefault(); const result = await mutate(() => post<{ board: Board }>('/boards', { title: newBoardTitle, workspaceId: newBoardWorkspace || boot.workspaces[0]?.id, visibility: newBoardVisibility }), 'Quadro criado'); if (result?.board?.id) { setModal(null); setNewBoardTitle(''); openBoard(result.board.id); } };
  const createInvite = async (e: React.FormEvent) => { e.preventDefault(); if (!ownerWorkspace) return; const result = await mutate(() => post<{ invite: { token: string; inviteUrl: string } }>(`/workspaces/${ownerWorkspace}/invites`, { email: inviteEmail, role: inviteRole, boardId: currentBoard?.id }), 'Convite criado'); if (result?.invite) setInviteLink(`${location.origin}/invite/${result.invite.token}`); };
  const createAutomation = async (e: React.FormEvent) => { e.preventDefault(); if (!detail) return; const action: Record<string, unknown> = { type: automationAction }; if (automationAction === 'add_label') action.labelId = automationValue; if (automationAction === 'move_card') action.listId = automationValue; if (automationAction === 'post_comment') action.body = automationValue; if (automationAction === 'set_due') action.daysFromNow = Number(automationValue); const result = await mutate(() => post(`/boards/${detail.board.id}/automations`, { name: automationName, trigger: automationTrigger, actions: [action], enabled: true }), 'Regra criada'); if (result) { setAutomationName(''); setAutomationValue(''); } };
  const doLogout = async () => { await post('/auth/logout'); setBoot(null); setDetail(null); setCardId(null); navigate('home'); };
  const toggleBoardFocus = () => {
    const next = !boardFocus;
    setBoardFocus(next); setSidebarOpen(false); setTopMenu(null); setFilterOpen(false);
    requestAnimationFrame(() => document.querySelector<HTMLButtonElement>(next ? '.focus-restore' : '.focus-toggle')?.focus());
  };
  return <div className={`app-shell ${page === 'board' && boardFocus ? 'board-focus' : ''}`}>
    <header className={`global-header ${page === 'board' && detail ? 'board-global-header' : ''}`}><button className="icon-button mobile-menu" aria-label="Abrir menu" onClick={() => setSidebarOpen(v => !v)}><Menu size={21} /></button><button className="brand" onClick={() => navigate('home')}><span className="brand-mark"><i /><i /><i /></span><strong>Organize</strong></button><div className="header-nav"><button className="header-link" onClick={() => setTopMenu(v => v === 'boards' ? null : 'boards')}>Áreas de trabalho <ChevronDown size={14} /></button><button className="header-link" onClick={() => setTopMenu(v => v === 'recent' ? null : 'recent')}>Recentes <ChevronDown size={14} /></button><button className="header-link" onClick={() => setTopMenu(v => v === 'favorites' ? null : 'favorites')}>Favoritos</button><button className="header-link" onClick={() => setTopMenu(v => v === 'templates' ? null : 'templates')}>Modelos</button></div><button className="create-button" onClick={() => setTopMenu(v => v === 'create' ? null : 'create')}><Plus size={17} /> <span>Criar</span></button><div className="header-spacer" />{page === 'board' && detail && <button className="header-focus-toggle focus-toggle" aria-label="Recolher menus e barra superior" onClick={toggleBoardFocus}><Maximize2 size={16} /><span>Foco</span></button>}<button className="global-search" onClick={() => navigate('search')}><Search size={17} /><span>Buscar</span><kbd>/</kbd></button><button className="icon-button header-icon" title="Notificações" onClick={() => setTopMenu(v => v === 'notifications' ? null : 'notifications')}><Bell size={19} />{boot.notifications.some(n => !n.readAt) && <span className="unread-dot" />}</button><button className="icon-button header-icon" title="Ajuda e atalhos" onClick={() => flash('Atalhos: / buscar, b quadros, f filtrar, n novo cartão, Alt + seta mover cartão, Esc fechar.')}><CircleHelp size={19} /></button><button className="avatar-button" title="Conta" onClick={() => setTopMenu(v => v === 'profile' ? null : 'profile')}><Avatar person={boot.user} /></button></header>
    {topMenu && <><div className="click-catcher" onClick={() => setTopMenu(null)} /><div className={`top-popover top-popover-${topMenu}`}>
      {topMenu === 'create' && <><h3>Criar</h3><button onClick={() => { setModal('board'); setTopMenu(null); }}><LayoutGrid size={17} /> Quadro</button><button onClick={() => { setModal('workspace'); setTopMenu(null); }}><Users size={17} /> Área de trabalho</button></>}
      {topMenu === 'boards' && <><h3>Seus quadros</h3>{boot.boards.filter(b => !b.archived).map(b => <button key={b.id} onClick={() => openBoard(b.id)}><span className="board-mini" style={{ background: b.background || '#0b6bcb' }} />{b.title}</button>)}<button onClick={() => { setModal('board'); setTopMenu(null); }}><Plus size={17} /> Criar quadro</button></>}
      {topMenu === 'recent' && <><h3>Quadros recentes</h3>{recentIds.map(id => boot.boards.find(board => board.id === id)).filter((board): board is Board => !!board && !board.archived).map(board => <button key={board.id} onClick={() => openBoard(board.id)}><span className="board-mini" style={{ background: board.background || '#0b6bcb' }} />{board.title}</button>)}{!recentIds.length && <p className="empty-small">Os quadros que você abrir aparecerão aqui.</p>}</>}
      {topMenu === 'favorites' && <><h3>Favoritos</h3>{boot.boards.filter(board => board.starred && !board.archived).map(board => <button key={board.id} onClick={() => openBoard(board.id)}><Star size={16} fill="currentColor" />{board.title}</button>)}{!boot.boards.some(board => board.starred && !board.archived) && <p className="empty-small">Marque um quadro com a estrela para encontrá-lo aqui.</p>}</>}
      {topMenu === 'templates' && <><h3>Modelos de cartões</h3>{templateCards.map(card => <button key={card.id} onClick={() => { openBoard(card.boardId); setCardId(card.id); }}><CheckSquare size={16} />{card.title}<small>{card.boardTitle}</small></button>)}{!templateCards.length && <p className="empty-small">Abra um cartão e escolha Ações → Tornar modelo.</p>}</>}
      {topMenu === 'notifications' && <><h3>Notificações</h3>{boot.notifications.length ? boot.notifications.slice(0, 12).map(n => <button className={`notification-row ${n.readAt ? '' : 'is-unread'}`} key={n.id} onClick={() => { mutate(() => patch(`/notifications/${n.id}`, { read: true })); if (n.body?.boardId) openBoard(n.body.boardId); if (n.body?.cardId) setCardId(n.body.cardId); setTopMenu(null); }}><b>{notificationText(n.type)}</b><span>{new Date(n.createdAt).toLocaleString('pt-BR')}</span></button>) : <p className="empty-small">Tudo em dia por aqui.</p>}</>}
      {topMenu === 'profile' && <><div className="profile-pop"><Avatar person={boot.user} /><div><strong>{boot.user.name}</strong><small>{boot.user.email}</small></div></div><button onClick={() => void theme.changeAppearance(theme.effective === 'dark' ? 'light' : 'dark')} disabled={theme.saving}>{theme.effective === 'dark' ? <Sun size={17} /> : <Moon size={17} />}{theme.effective === 'dark' ? 'Modo claro' : 'Modo escuro'}</button><button onClick={() => navigate('settings')}><Settings2 size={17} /> Configurações</button>{!pwa.installed && <button onClick={() => { setTopMenu(null); void pwa.install(); }}><Download size={17} /> Instalar Organize</button>}<button onClick={doLogout}><LogOut size={17} /> Sair</button></>}
    </div></>}
    <div className="body-shell"><aside className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}><div className="sidebar-main"><button className={`side-item ${page === 'home' ? 'active' : ''}`} onClick={() => navigate('home')}><Grid2X2 size={18} /> Quadros</button><button className={`side-item ${page === 'inbox' ? 'active' : ''}`} onClick={() => navigate('inbox')}><Inbox size={18} /> Caixa de entrada</button><button className={`side-item ${page === 'planner' ? 'active' : ''}`} onClick={() => navigate('planner')}><CalendarDays size={18} /> Planejamento</button><button className={`side-item ${page === 'search' ? 'active' : ''}`} onClick={() => navigate('search')}><Search size={18} /> Busca</button></div><div className="side-rule" /><div className="side-heading"><span>Áreas de trabalho</span><button className="icon-button" title="Criar área de trabalho" onClick={() => setModal('workspace')}><Plus size={16} /></button></div>{boot.workspaces.map(w => <div className="workspace-group" key={w.id}><button className="workspace-title" onClick={() => navigate('home')}><span className="workspace-avatar">{initials(w.name)}</span><span>{w.name}</span><ChevronDown size={15} /></button><div className="workspace-boards">{boot.boards.filter(b => b.workspaceId === w.id && !b.archived).map(b => <button className={`side-board ${boardId === b.id && page === 'board' ? 'active' : ''}`} key={b.id} onClick={() => openBoard(b.id)}><span className="board-mini" style={{ background: b.background || '#0b6bcb' }} /> <span>{b.title}</span>{b.starred && <Star size={13} fill="currentColor" />}</button>)}</div></div>)}</aside>
    <main className={`main-content ${page === 'board' ? 'main-board' : ''}`}>
      {page === 'home' && <HomePage boot={boot} openBoard={openBoard} onNewBoard={() => setModal('board')} onNewWorkspace={() => setModal('workspace')} onStar={id => mutate(() => patch(`/boards/${id}`, { starred: !boot.boards.find(b => b.id === id)?.starred }))} />}
      {page === 'board' && detail && <><div className="board-background" style={{ background: detail.board.background || 'linear-gradient(125deg, #075c90, #0e7490 55%, #135ba1)' }} /><div className="board-topbar"><div className="board-heading"><h1>{detail.board.title}</h1><button className="board-head-icon" title={detail.board.starred ? 'Remover favorito' : 'Favoritar'} onClick={() => mutate(() => patch(`/boards/${detail.board.id}`, { starred: !detail.board.starred }))}><Star size={18} fill={detail.board.starred ? 'currentColor' : 'none'} /></button><span className="visibility-pill">{detail.board.visibility === 'private' ? 'Privado' : detail.board.visibility === 'public' ? 'Público' : 'Área de trabalho'}</span></div><div className="board-actions"><div className="member-stack">{detail.members.slice(0, 5).map(m => <Avatar key={m.id} person={m} size="small" />)}</div><button className="board-action" onClick={() => { setModal('invite'); setInviteLink(''); }}><Users size={16} /><span>Compartilhar</span></button><button className="board-action" onClick={() => setFilterOpen(v => !v)}><Filter size={16} /><span>Filtro</span></button><button className="board-action" onClick={() => setModal('automation')}><Zap size={16} /><span>Automação</span></button><button className="board-head-icon" title="Configurações do quadro" onClick={() => setModal('board-settings')}><MoreHorizontal size={20} /></button></div></div>{boardFocus && <button className="focus-restore" aria-label="Mostrar menus e barra superior" onClick={toggleBoardFocus}><Minimize2 size={16} /><span>Mostrar menus</span></button>}<div className="view-bar"><div className="view-tabs">{views.map(v => <button key={v.id} className={`view-tab ${view === v.id ? 'selected' : ''}`} onClick={() => setView(v.id)}><v.icon size={16} />{v.label}</button>)}</div></div>{filterOpen && <BoardFilterPanel boardId={detail.board.id} labels={detail.labels} members={detail.members} values={{ text: filterText, labelId: filterLabel, memberId: filterMember, due: filterDue }} onChange={(field, value) => { if (field === 'text') setFilterText(value); if (field === 'labelId') setFilterLabel(value); if (field === 'memberId') setFilterMember(value); if (field === 'due') setFilterDue(value); }} onApply={values => { setFilterText(values.text); setFilterLabel(values.labelId); setFilterMember(values.memberId); setFilterDue(values.due); }} onClose={() => setFilterOpen(false)} flash={flash} />}
      {view === 'board' ? <BoardCanvas detail={{ ...detail, cards: filteredCards }} onCard={setCardId} mutate={mutate} flash={flash} /> : <AlternateView view={view} detail={{ ...detail, cards: filteredCards }} onCard={setCardId} mutate={mutate} />}
      <nav className="board-bottom-nav"><button onClick={() => navigate('inbox')}><Inbox size={18} /> <span>Entrada</span></button><button onClick={() => navigate('planner')}><CalendarDays size={18} /> <span>Planejamento</span></button><button className="selected" onClick={() => setView('board')}><LayoutGrid size={18} /> <span>Quadro</span></button><button onClick={() => setTopMenu('boards')}><Grid2X2 size={18} /> <span>Trocar</span></button></nav></>}
      {page === 'board' && !detail && <div className="content-loading">Carregando quadro…</div>}
      {page === 'search' && <section className="content-page"><div className="page-title"><Search size={24} /><div><h1>Buscar</h1><p>Encontre quadros e cartões em todas as suas áreas de trabalho.</p></div></div><div className="large-search"><Search size={20} /><input className="search-page-input" autoFocus placeholder="Buscar em todo o Organize" value={query} onChange={e => setQuery(e.target.value)} /></div>{query && <div className="search-results"><h2>Quadros</h2>{searchResults.boards?.length ? searchResults.boards.map(b => <button className="result-row" key={b.id} onClick={() => openBoard(b.id)}><span className="board-mini" style={{ background: b.background || '#0b6bcb' }} />{b.title}<ChevronRight size={16} /></button>) : <p>Nenhum quadro encontrado.</p>}<h2>Cartões</h2>{searchResults.cards?.length ? searchResults.cards.map(c => <button className="result-row" key={c.id} onClick={() => { openBoard(c.boardId); setCardId(c.id); }}><LayoutGrid size={16} />{c.title}<ChevronRight size={16} /></button>) : <p>Nenhum cartão encontrado.</p>}</div>}</section>}
      {page === 'inbox' && <InboxPage boot={boot} openBoard={openBoard} mutate={mutate} flash={flash} />}
      {page === 'planner' && <PlannerPage boot={boot} openBoard={openBoard} mutate={mutate} flash={flash} />}
      {page === 'settings' && <SettingsPage boot={boot} mutate={mutate} flash={flash} appearance={theme.appearance} appearanceSaving={theme.saving} onAppearanceChange={theme.changeAppearance} />}
    </main></div>
    {cardId && cardDetail && detail && <CardDialog key={cardId} data={cardDetail} board={detail} user={boot.user} onClose={() => setCardId(null)} mutate={mutate} reload={() => loadCard(cardId)} flash={flash} />}
    {modal === 'workspace' && <Dialog title="Criar área de trabalho" onClose={() => setModal(null)}><form className="dialog-form" onSubmit={createWorkspace}><p>Reúna quadros e pessoas em um espaço compartilhado.</p><label>Nome da área de trabalho<input autoFocus required value={workspaceName} onChange={e => setWorkspaceName(e.target.value)} placeholder="Ex.: Equipe de Produto" /></label><button className="primary-button">Criar área de trabalho</button></form></Dialog>}
    {modal === 'board' && <Dialog title="Criar quadro" onClose={() => setModal(null)}><form className="dialog-form" onSubmit={createBoard}><div className="board-preview"><div className="board-preview-list"><span /><span /><span /></div><div className="board-preview-list"><span /><span /></div></div><label>Título do quadro<input autoFocus required value={newBoardTitle} onChange={e => setNewBoardTitle(e.target.value)} placeholder="Ex.: Planejamento da equipe" /></label><label>Área de trabalho<select required value={newBoardWorkspace || boot.workspaces[0]?.id || ''} onChange={e => setNewBoardWorkspace(e.target.value)}>{boot.workspaces.map(w => <option value={w.id} key={w.id}>{w.name}</option>)}</select></label><label>Visibilidade<select value={newBoardVisibility} onChange={e => setNewBoardVisibility(e.target.value as Board['visibility'])}><option value="workspace">Área de trabalho</option><option value="private">Privado</option><option value="public">Público</option></select></label><button className="primary-button" disabled={!boot.workspaces.length}>Criar quadro</button>{!boot.workspaces.length && <p className="inline-hint">Crie uma área de trabalho primeiro.</p>}</form></Dialog>}
    {modal === 'invite' && <Dialog title="Compartilhar quadro" onClose={() => setModal(null)}><form className="dialog-form" onSubmit={createInvite}><p>Convide pessoas para colaborar em <strong>{currentBoard?.title}</strong>.</p><label>Email<input type="email" autoFocus required value={inviteEmail} onChange={e => setInviteEmail(e.target.value)} placeholder="pessoa@exemplo.com" /></label><label>Permissão<select value={inviteRole} onChange={e => setInviteRole(e.target.value)}><option value="member">Membro — pode editar</option><option value="observer">Observador — somente leitura</option><option value="admin">Administrador</option></select></label><button className="primary-button">Gerar convite</button>{inviteLink && <div className="invite-result"><span>Link de convite criado. Copie e envie à pessoa:</span><div><input readOnly value={inviteLink} /><button type="button" className="secondary-button" onClick={() => { navigator.clipboard.writeText(inviteLink); flash('Link copiado'); }}>Copiar</button></div><small>Envio por email requer configuração SMTP externa.</small></div>}</form></Dialog>}
    {modal === 'automation' && detail && <Dialog title="Automações" onClose={() => setModal(null)} wide><div className="automation-layout"><div><p>Regras do quadro</p>{detail.automations?.length ? detail.automations.map(a => <div className="automation-row" key={a.id}><Zap size={17} /><div><strong>{a.name}</strong><small>{a.trigger} → {a.actions?.map(action => action.type).join(', ')}</small></div><button className="subtle-button" onClick={() => mutate(() => patch(`/automations/${a.id}`, { enabled: !a.enabled }))}>{a.enabled ? 'Pausar' : 'Ativar'}</button></div>) : <p className="empty-small">Nenhuma regra criada.</p>}</div><form className="dialog-form" onSubmit={createAutomation}><h3>Nova regra</h3><label>Nome<input required value={automationName} onChange={e => setAutomationName(e.target.value)} placeholder="Ex.: Marcar como concluído" /></label><label>Quando<select value={automationTrigger} onChange={e => setAutomationTrigger(e.target.value)}><option value="card_moved">Cartão for movido</option><option value="card_created">Cartão for criado</option><option value="due">Data de entrega chegar</option><option value="button">Ao clicar no botão do cartão</option></select></label><label>Então<select value={automationAction} onChange={e => { setAutomationAction(e.target.value); setAutomationValue(''); }}><option value="mark_complete">Concluir cartão</option><option value="add_label">Adicionar etiqueta</option><option value="move_card">Mover para lista</option><option value="post_comment">Publicar comentário</option><option value="set_due">Definir entrega em dias</option><option value="archive_card">Arquivar cartão</option></select></label>{automationAction === 'add_label' && <label>Etiqueta<select required value={automationValue} onChange={e => setAutomationValue(e.target.value)}><option value="">Selecione</option>{detail.labels.map(l => <option value={l.id} key={l.id}>{l.name}</option>)}</select></label>}{automationAction === 'move_card' && <label>Lista<select required value={automationValue} onChange={e => setAutomationValue(e.target.value)}><option value="">Selecione</option>{detail.lists.filter(l => !l.archived).map(l => <option value={l.id} key={l.id}>{l.title}</option>)}</select></label>}{automationAction === 'post_comment' && <label>Comentário<input required value={automationValue} onChange={e => setAutomationValue(e.target.value)} placeholder="Mensagem automática" /></label>}{automationAction === 'set_due' && <label>Dias a partir de hoje<input required type="number" min="0" value={automationValue} onChange={e => setAutomationValue(e.target.value)} /></label>}<button className="primary-button">Criar regra</button></form></div></Dialog>}
    {modal === 'board-settings' && detail && <Dialog title="Configurações do quadro" onClose={() => setModal(null)} wide><div className="dialog-form"><label>Nome do quadro<input defaultValue={detail.board.title} onBlur={e => { if (e.target.value.trim() && e.target.value !== detail.board.title) mutate(() => patch(`/boards/${detail.board.id}`, { title: e.target.value.trim() }), 'Nome atualizado'); }} /></label><label>Descrição<textarea defaultValue={detail.board.description || ''} onBlur={e => { if (e.target.value !== detail.board.description) mutate(() => patch(`/boards/${detail.board.id}`, { description: e.target.value }), 'Descrição atualizada'); }} /></label><label>Visibilidade<select disabled={detail.board.role !== 'admin'} value={detail.board.visibility} onChange={e => mutate(() => patch(`/boards/${detail.board.id}`, { visibility: e.target.value }), 'Visibilidade atualizada')}><option value="private">Privado</option><option value="workspace">Área de trabalho</option><option value="public">Público</option></select></label><label>Cor de fundo<input type="color" value={/^#[0-9a-f]{6}$/i.test(detail.board.background || '') ? detail.board.background : '#0b6bcb'} onChange={e => mutate(() => patch(`/boards/${detail.board.id}`, { background: e.target.value }))} /></label><button className="secondary-button" onClick={async () => { try { const data = await get(`/workspaces/${detail.board.workspaceId}/export`); saveJson(`organize-${detail.board.workspaceId}.json`, data); } catch (err) { flash((err as Error).message); } }}><FileDown size={16} /> Exportar área de trabalho</button><button className="danger-button" disabled={detail.board.role !== 'admin'} onClick={async () => { const result = await mutate(() => patch(`/boards/${detail.board.id}`, { archived: true }), 'Quadro arquivado'); if (result) { setModal(null); navigate('home'); } }}><Archive size={16} /> Arquivar quadro</button></div><BoardAdminPanels detail={detail} currentUserId={boot.user.id} onChanged={() => loadBoard(detail.board.id)} onOpenCard={id => { setModal(null); setCardId(id); }} onInvite={() => { setModal('invite'); setInviteLink(''); }} /></Dialog>}
    {toast && <div className="toast" role="status">{toast}<button onClick={() => setToast('')} aria-label="Fechar"><X size={15} /></button></div>}
    {pwa.helpOpen && <InstallHelp onClose={pwa.closeHelp} />}
  </div>;
}

function HomePage({ boot, openBoard, onNewBoard, onNewWorkspace, onStar }: { boot: Bootstrap; openBoard: (id: string) => void; onNewBoard: () => void; onNewWorkspace: () => void; onStar: (id: string) => void }) {
  const boards = boot.boards.filter(b => !b.archived); const starred = boards.filter(b => b.starred);
  return <section className="home-page"><div className="welcome"><div><div className="eyebrow">BOM TRABALHO COMEÇA AQUI</div><h1>Olá, {boot.user.name.split(' ')[0]} <span>👋</span></h1><p>Um espaço para cada projeto e clareza em cada tarefa.</p></div><button className="primary-button" onClick={onNewBoard}><Plus size={18} /> Criar quadro</button></div>{starred.length > 0 && <section className="boards-section"><h2><Star size={18} /> Favoritos</h2><div className="boards-grid">{starred.map(b => <BoardTile key={b.id} board={b} openBoard={openBoard} onStar={onStar} />)}</div></section>}{boot.workspaces.map(w => <section className="boards-section" key={w.id}><div className="section-title"><div className="workspace-avatar">{initials(w.name)}</div><h2>{w.name}</h2><span>{w.role || 'Membro'}</span></div><div className="boards-grid">{boards.filter(b => b.workspaceId === w.id).map(b => <BoardTile key={b.id} board={b} openBoard={openBoard} onStar={onStar} />)}<button className="new-board-tile" onClick={onNewBoard}><Plus size={20} /><strong>Criar novo quadro</strong></button></div></section>)}{boot.workspaces.length === 0 && <div className="empty-home"><div className="empty-illustration"><span className="brand-mark"><i /><i /><i /></span></div><h2>Seu espaço começa aqui</h2><p>Crie uma área de trabalho para organizar seus quadros e convidar sua equipe.</p><button className="primary-button" onClick={onNewWorkspace}><Plus size={17} /> Criar área de trabalho</button></div>}<button className="text-button new-workspace-link" onClick={onNewWorkspace}><Plus size={16} /> Criar outra área de trabalho</button></section>;
}
function BoardTile({ board, openBoard, onStar }: { board: Board; openBoard: (id: string) => void; onStar: (id: string) => void }) { return <div className="board-tile" style={{ background: board.background || 'linear-gradient(135deg,#0b6bcb,#064b80)' }}><button className="board-tile-main" onClick={() => openBoard(board.id)}><strong>{board.title}</strong></button><button className="tile-star" title={board.starred ? 'Remover favorito' : 'Favoritar'} onClick={() => onStar(board.id)}><Star size={18} fill={board.starred ? 'currentColor' : 'none'} /></button></div>; }

function InboxPage({ boot, openBoard, mutate, flash }: { boot: Bootstrap; openBoard: (id: string) => void; mutate: <T>(fn: () => Promise<T>, message?: string) => Promise<T | null>; flash: (s: string) => void }) {
  const [items, setItems] = useState<{ id: string; title: string; createdAt: string; completed?: boolean }[]>([]); const [title, setTitle] = useState('');
  const [destinations, setDestinations] = useState<Record<string, { boardId: string; listId: string; lists: { id: string; title: string }[] }>>({});
  const refresh = useCallback(() => { get<{ items: { id: string; title: string; createdAt: string }[] }>('/inbox').then(v => setItems(v.items || [])).catch(err => flash((err as Error).message)); }, [flash]);
  useEffect(refresh, [refresh]);
  return <section className="content-page"><div className="page-title"><Inbox size={26} /><div><h1>Caixa de entrada</h1><p>Capture ideias agora. Organize nos quadros quando estiver pronto.</p></div></div><form className="inbox-compose" onSubmit={async e => { e.preventDefault(); if (!title.trim()) return; const result = await mutate(() => post('/inbox', { title: title.trim() }), 'Item adicionado'); if (result) { setTitle(''); refresh(); } }}><Plus size={19} /><input value={title} onChange={e => setTitle(e.target.value)} placeholder="Adicione uma ideia ou tarefa…" /><button className="primary-button">Adicionar</button></form><div className="inbox-list">{items.filter(item => !item.completed).map(item => <div className="inbox-item" key={item.id}><div><strong>{item.title}</strong><small>{new Date(item.createdAt).toLocaleDateString('pt-BR')}</small></div><select value={destinations[item.id]?.boardId || ''} aria-label="Selecionar quadro" onChange={async e => { const boardId = e.target.value; if (!boardId) return; try { const data = await get<BoardDetail>(`/boards/${boardId}`); const lists = data.lists.filter(l => !l.archived).map(l => ({ id: l.id, title: l.title })); setDestinations(v => ({ ...v, [item.id]: { boardId, listId: lists[0]?.id || '', lists } })); } catch (err) { flash((err as Error).message); } }}><option value="">Mover para quadro…</option>{boot.boards.filter(b => !b.archived).map(b => <option key={b.id} value={b.id}>{b.title}</option>)}</select>{destinations[item.id]?.lists.length > 0 && <><select aria-label="Selecionar lista" value={destinations[item.id].listId} onChange={e => setDestinations(v => ({ ...v, [item.id]: { ...v[item.id], listId: e.target.value } }))}>{destinations[item.id].lists.map(l => <option key={l.id} value={l.id}>{l.title}</option>)}</select><button className="secondary-button" onClick={async () => { const listId = destinations[item.id]?.listId; if (!listId) return; const result = await mutate(() => post(`/inbox/${item.id}/move`, { boardId: destinations[item.id].boardId, listId }), 'Cartão movido para o quadro'); if (result) refresh(); }}>Mover</button></>}<button className="icon-button" title="Arquivar" onClick={async () => { await mutate(() => patch(`/inbox/${item.id}`, { completed: true }), 'Item arquivado'); refresh(); }}><Archive size={17} /></button></div>)}{items.filter(item => !item.completed).length === 0 && <div className="empty-state"><Inbox size={38} /><h2>Caixa de entrada vazia</h2><p>Adicione sua primeira ideia no campo acima.</p></div>}</div><div className="info-card"><WandSparkles size={19} /><span>Captura por email, Slack e Teams depende de integrações externas. Você pode adicionar itens diretamente aqui.</span></div><button className="text-button" onClick={() => openBoard(boot.boards[0]?.id)} disabled={!boot.boards.length}>Ir para seu primeiro quadro</button></section>;
}
function PlannerPage({ boot, openBoard, flash }: { boot: Bootstrap; openBoard: (id: string) => void; mutate: unknown; flash: (s: string) => void }) {
  const [cards, setCards] = useState<Card[]>([]); const [date, setDate] = useState(new Date());
  const year = date.getFullYear(), month = date.getMonth(), first = new Date(year, month, 1).getDay(), last = new Date(year, month + 1, 0).getDate();
  useEffect(() => { const from = new Date(Date.UTC(year, month, 1)).toISOString(); const to = new Date(Date.UTC(year, month + 1, 1) - 1).toISOString(); get<{ cards: Card[] }>(`/planner?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`).then(v => setCards(v.cards || [])).catch(err => flash((err as Error).message)); }, [year, month, flash]);
  const cells = Array.from({ length: first + last }, (_, i) => i < first ? null : i - first + 1);
  return <section className="content-page"><div className="page-title"><CalendarDays size={26} /><div><h1>Planejamento</h1><p>Veja entregas de todos os quadros em um só calendário.</p></div></div><div className="planner-toolbar"><button className="icon-button" onClick={() => setDate(new Date(year, month - 1, 1))}><ChevronLeft size={19} /></button><h2>{date.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}</h2><button className="icon-button" onClick={() => setDate(new Date(year, month + 1, 1))}><ChevronRight size={19} /></button><button className="secondary-button" onClick={() => setDate(new Date())}>Hoje</button></div><div className="calendar-grid">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d => <div className="calendar-weekday" key={d}>{d}</div>)}{cells.map((day, i) => <div className={`calendar-cell ${day === new Date().getDate() && month === new Date().getMonth() && year === new Date().getFullYear() ? 'today' : ''}`} key={i}>{day && <><span className="calendar-date">{day}</span>{cards.filter(c => c.dueAt && new Date(c.dueAt).getDate() === day && new Date(c.dueAt).getMonth() === month && new Date(c.dueAt).getFullYear() === year).map(c => <button className="calendar-event" key={c.id} onClick={() => openBoard(c.boardId)}>{c.title}</button>)}</>}</div>)}</div><div className="info-card"><Clock3 size={19} /><span>Conectar Google Calendar ou Outlook e reservar blocos de foco requer credenciais externas.</span></div><small>{cards.length} cartão(ões) com data de entrega.</small><small className="muted"> {boot.workspaces.length} área(s) de trabalho.</small></section>;
}
function AppearanceSettings({ appearance, saving, onChange }: { appearance: Appearance; saving: boolean; onChange: (next: Appearance) => Promise<void> }) {
  const choices: { id: Appearance; label: string; icon: typeof Sun }[] = [
    { id: 'light', label: 'Claro', icon: Sun }, { id: 'dark', label: 'Escuro', icon: Moon }, { id: 'system', label: 'Sistema', icon: Monitor },
  ];
  return <section className="settings-card"><h2>Aparência</h2><p>Escolha como o Organize aparece nesta conta.</p><div className="appearance-choices" role="group" aria-label="Aparência">{choices.map(choice => <button key={choice.id} className={`appearance-choice ${appearance === choice.id ? 'selected' : ''}`} aria-pressed={appearance === choice.id} disabled={saving} onClick={() => void onChange(choice.id)}><choice.icon size={18} />{choice.label}</button>)}</div></section>;
}
function SettingsPage({ boot, mutate, flash, appearance, appearanceSaving, onAppearanceChange }: { boot: Bootstrap; mutate: <T>(fn: () => Promise<T>, message?: string) => Promise<T | null>; flash: (s: string) => void; appearance: Appearance; appearanceSaving: boolean; onAppearanceChange: (next: Appearance) => Promise<void> }) {
  const [name, setName] = useState(boot.user.name); const [oldPassword, setOldPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [workspaceId, setWorkspaceId] = useState(boot.workspaces[0]?.id || ''); const file = useRef<HTMLInputElement>(null);
  return <section className="content-page settings-page"><div className="page-title"><Settings2 size={26} /><div><h1>Configurações</h1><p>Gerencie sua conta e os dados das áreas de trabalho.</p></div></div><div className="settings-grid"><AppearanceSettings appearance={appearance} saving={appearanceSaving} onChange={onAppearanceChange} /><section className="settings-card"><h2>Perfil</h2><label>Nome<input value={name} onChange={e => setName(e.target.value)} /></label><label>Email<input type="email" value={boot.user.email} readOnly title="Alteração de email ainda não disponível" /></label><button className="primary-button" onClick={() => mutate(() => patch('/me', { name }), 'Perfil atualizado')}>Salvar perfil</button></section><section className="settings-card"><h2>Segurança</h2><label>Senha atual<input type="password" value={oldPassword} onChange={e => setOldPassword(e.target.value)} /></label><label>Nova senha<input type="password" minLength={8} value={newPassword} onChange={e => setNewPassword(e.target.value)} /></label><button className="secondary-button" onClick={async () => { if (newPassword.length < 8 || !oldPassword) { flash('Informe sua senha atual e uma nova senha de pelo menos 8 caracteres.'); return; } const result = await mutate(() => post('/me/password', { oldPassword, newPassword }), 'Senha atualizada'); if (result) { setOldPassword(''); setNewPassword(''); } }}>Alterar senha</button></section><section className="settings-card"><h2>Dados</h2><p>Exporte ou importe um backup JSON de uma área de trabalho.</p><label>Área de trabalho<select value={workspaceId} onChange={e => setWorkspaceId(e.target.value)}>{boot.workspaces.map(w => <option value={w.id} key={w.id}>{w.name}</option>)}</select></label><div className="settings-actions"><button className="secondary-button" disabled={!workspaceId} onClick={async () => { try { const data = await get(`/workspaces/${workspaceId}/export`); saveJson(`organize-${workspaceId}.json`, data); } catch (err) { flash((err as Error).message); } }}><FileDown size={16} /> Exportar JSON</button><button className="secondary-button" disabled={!workspaceId} onClick={() => file.current?.click()}>Importar JSON</button><input ref={file} type="file" accept="application/json,.json" hidden onChange={async e => { const f = e.target.files?.[0]; if (!f) return; try { const data = JSON.parse(await f.text()); await mutate(() => post(`/workspaces/${workspaceId}/import`, data), 'Dados importados'); } catch (err) { flash((err as Error).message); } e.target.value = ''; }} /></div></section><section className="settings-card"><h2>Atalhos de teclado</h2><p><kbd>/</kbd> Buscar <kbd>b</kbd> Quadros <kbd>f</kbd> Filtro <kbd>n</kbd> Novo cartão <kbd>Esc</kbd> Fechar</p></section></div></section>;
}
